function validate(input) {
  const [{ library_books = [], borrowing_records = [] }] = input;
  const copies = new Map(), titles = new Set(), records = new Set(), open = new Map();
  for (const [id, title, , , , total] of library_books) {
    if (id === null || title === null || total === null) return 'book_id, title and total_copies cannot be null.';
    if (copies.has(id)) return `book_id ${id} appears twice in library_books.`;
    const key = String(title).toLowerCase();
    if (titles.has(key)) return `The title ${title} appears twice in library_books.`;
    titles.add(key);
    if (!(total > 0)) return 'total_copies must be positive.';
    copies.set(id, total);
  }
  for (const [id, book, , borrowed, returned] of borrowing_records) {
    if (id === null || book === null || borrowed === null) return 'record_id, book_id and borrow_date cannot be null.';
    if (records.has(id)) return `record_id ${id} appears twice in borrowing_records.`;
    records.add(id);
    if (!copies.has(book)) return `book_id ${book} is not in library_books.`;
    if (returned !== null && returned < borrowed) return `Record ${id} is returned before it was borrowed.`;
    if (returned === null) open.set(book, (open.get(book) ?? 0) + 1);
  }
  for (const [book, count] of open) if (count > copies.get(book)) return `Book ${book} has more open loans than copies.`;
  return null;
}

