function generate(rand, size) {
  const small = size === 'small';
  const int = n => Math.floor(rand() * n);
  const pick = list => list[int(list.length)];
  const pad = n => String(n).padStart(2, '0');
  const authors = ['Jane Austen', 'George Orwell', 'Harper Lee', 'Aldous Huxley', 'F. Scott', 'Toni Morrison'];
  const genres = ['Fiction', 'Dystopian', 'Romance', 'Mystery'];
  const people = ['Alice Smith', 'Bob Johnson', 'Carol White', 'David Brown', 'Emma Wilson', 'Frank Davis', 'Grace Miller', 'Henry Taylor'];
  const titles = ['Brave New World', 'Dune', 'Emma', '1984', 'Beloved', 'Ulysses', 'Persuasion', 'Middlemarch'];
  for (let i = titles.length - 1; i > 0; i--) { const j = int(i + 1); [titles[i], titles[j]] = [titles[j], titles[i]]; }
  const words = ['Silent', 'Golden', 'Hidden', 'Northern', 'Paper', 'Winter'];
  const bookCount = small ? int(7) : 400, cap = small ? 8 : 2000;
  const library_books = [], loans = [];
  for (let id = 1; id <= bookCount; id++) {
    const copies = 1 + int(small ? 3 : 5);
    library_books.push([id, small ? titles[id - 1] : `${pick(words)} Volume ${id}`, pick(authors), pick(genres), 1800 + int(225), copies]);
    // About half the books are fully lent out; open loans never exceed the copies owned.
    const open = rand() < 0.5 ? copies : int(copies + 1), returned = int(3);
    for (let k = 0; k < open + returned; k++) {
      const month = 1 + int(10), day = 1 + int(28);
      const borrowed = `2024-${pad(month)}-${pad(day)}`;
      const back = k < open ? null : `2024-${pad(month + 1 + int(2))}-${pad(1 + int(28))}`;
      loans.push([id, pick(people), borrowed, back]);
    }
  }
  for (let i = loans.length - 1; i > 0; i--) { const j = int(i + 1); [loans[i], loans[j]] = [loans[j], loans[i]]; }
  const borrowing_records = loans.slice(0, cap).map((loan, i) => [i + 1, ...loan]);
  return [{ library_books, borrowing_records }];
}
